/* No.008 */
(() => {
const TEX = {"front": "front.jpg", "back": "back.jpg", "sheen": "sheen.png", "glitter": "glitter.png"};
const FACE_H = {"b16": 1, "n": 240, "x0": -1, "x1": 1, "y0": 1, "y1": -1, "h": ""};
/* No.008 garnet-red button: the face is scooped away on the left so that side is thin;
   fine copper glitter gathers into a moving streak of light, like chatoyancy */
function buildH() {
  const grp = new THREE.Group();
  const Z0 = -.07, HS = .24, BE = -.1;
  const fm = bowMat(tex(TEX.front), loader.load(TEX.sheen), loader.load(TEX.glitter));
  fm.side = THREE.DoubleSide;
  fm.clearcoat = .9; fm.envMapIntensity = .3;
  // copper-red streak instead of the apricot one used on No.005
  const base = fm.onBeforeCompile;
  fm.onBeforeCompile = (sh) => {
    base(sh);
    sh.fragmentShader = sh.fragmentShader
      .replace('vec3(1.0, 0.64, 0.38), vec3(1.0, 0.76, 0.52)', 'vec3(1.0, 0.38, 0.2), vec3(1.0, 0.52, 0.28)')
      .replace('vec3(1.0, 0.46, 0.16), vec3(1.0, 0.6, 0.26)', 'vec3(1.0, 0.5, 0.25), vec3(1.0, 0.72, 0.38)')
      .replace('vec2 cell = floor(vUv * 120.0);', 'vec2 cell = floor(vUv * 260.0);')
      .replace('vec2 f = fract(vUv * 120.0) - 0.5;', 'vec2 f = fract(vUv * 260.0) - 0.5;');
  };
  const front = new THREE.Mesh(cloverRelief(FACE_H, Z0, HS), fm);
  front.onBeforeRender = (r, s, cam) => { fm.userData.uMV.value.setFromMatrix4(new THREE.Matrix4().multiplyMatrices(cam.matrixWorldInverse, front.matrixWorld)); };
  grp.add(front);
  // side wall
  grp.add(new THREE.Mesh(rim(1, Z0 + .003, BE, 200), new THREE.MeshPhysicalMaterial({ color: 0x4a1410, roughness: .25, clearcoat: 1, clearcoatRoughness: .05, envMapIntensity: .6 })));
  // back: shallow cone with two recessed slots and a small bridge between them (the photo is already mirrored)
  const CH = { cx: .03, cy: .0, ang: -.11, w: .2, L: .84, d: .1, bridge: .34 };
  const cone = (x, y) => { const r = Math.min(1, Math.hypot(x, y)); const t = Math.min(1, Math.max(0, (1 - r) / .55)); return -.13 * t * t * (3 - 2 * t); };
  const slot = (x, y) => {
    const dx = x - CH.cx, dy = y - CH.cy, ca = Math.cos(CH.ang), sa = Math.sin(CH.ang);
    const u = dx * ca + dy * sa, v = -dx * sa + dy * ca, au = Math.abs(u), hw = CH.w / 2;
    if (au > CH.L) return 0;
    const ends = Math.min(1, (CH.L - au) / .06);
    const side = Math.min(1, Math.max(0, (hw * Math.sqrt(Math.max(0, 1 - Math.pow(au / CH.L, 4))) - Math.abs(v)) / .02));
    return CH.d * ends * side * side * (3 - 2 * side);
  };
  const backZ = (x, y) => { const z = cone(x, y); return BE + z + Math.min(slot(x, y), -z); };
  const backMat = photoMat(tex(TEX.back), { roughness: .2, clearcoat: 1, clearcoatRoughness: .05, side: THREE.DoubleSide });
  const bg0 = cap(1, 64, 220, backZ, -1, false);
  grp.add(new THREE.Mesh(bg0, backMat));
  const hw = CH.w / 2 + .02, Hh = CH.d;
  const br = new THREE.Shape();
  br.moveTo(-hw, 0); br.lineTo(-hw, Hh); br.lineTo(hw, Hh); br.lineTo(hw, 0);
  br.lineTo(hw - .04, 0); br.lineTo(hw - .04, Hh * .35); br.quadraticCurveTo(0, Hh * .8, -hw + .04, Hh * .35); br.lineTo(-hw + .04, 0); br.closePath();
  const bgeo = new THREE.ExtrudeGeometry(br, { depth: CH.bridge, bevelEnabled: true, bevelThickness: .01, bevelSize: .01, bevelSegments: 3, curveSegments: 8 });
  bgeo.rotateX(-Math.PI / 2); bgeo.translate(0, -CH.bridge / 2, 0); bgeo.rotateZ(CH.ang - Math.PI / 2);
  bgeo.translate(CH.cx, CH.cy, BE + cone(CH.cx, CH.cy) + CH.d);
  const bp = bgeo.attributes.position, buv = bgeo.attributes.uv;
  for (let i = 0; i < bp.count; i++) buv.setXY(i, bp.getX(i) / 2 + .5, bp.getY(i) / 2 + .5);
  grp.add(new THREE.Mesh(bgeo, backMat));
  return grp;
}
viewer(document.getElementById('cv'), buildH, 'v');
})();
